window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5207ea108abe1e63"]={"versions": [{"id": "FIG-5207ea108abe1e63", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung von Ereignissen und zeitlichen Ereignismustern im Kontext des AUTOSAR Virtual Function Bus (VFB) Timing-Modells. Das Diagramm spezifiziert die strukturellen Beziehungen zwischen Ereignisdefinitionen, deren konkreten Instanziierungen bzw. Zeitpunkten sowie zugehörigen zeitlichen Garantien oder Restriktionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst folgende Klassen, Assoziationen und Vererbungsbeziehungen:</p>\n<ul class=\"fig-list\"><li><strong>Event</strong>: Abstrakte Basisentität eines Ereignisses (kursiv dargestellt).\n</li><li><strong>EventOccurrence</strong>: Repräsentiert ein konkretes Auftreten eines Ereignisses mit dem Attribut <code>+ occurrenceTime: TimePoint</code>. Verbunden mit <code>Event</code> über eine Assoziation mit Rollen und Kardinalitäten <code>1</code> (<code>+event</code>) zu <code>*</code> (<code>+occurrences</code>).\n</li><li><strong>EventConstraintOrGuarantee</strong>: Definiert Restriktionen oder Garantien für ein Ereignis mit dem Attribut <code>- constraint or guarantee:</code>. Assoziiert mit <code>Event</code> im Verhältnis <code>1 : 1</code> sowie mit <code>EventModel</code> über eine Assoziation mit Zielkardinalität <code>1</code>.\n</li><li><strong>EventModel</strong>: Abstrakte Basisklasse (kursiv dargestellt) für formale Zeitmodelle von Ereignissen.\n</li><li><strong>RecurringEventModel</strong>: Spezialisierung von <code>EventModel</code> (Generalisierungsbeziehung) zur Modellierung wiederkehrender Ereignisse mit den Attributen:\n<ul class=\"fig-list\"><li><code>+ lowestInterOccurrenceTime: TimeInterval</code>\n</li><li><code>+ highestInterOccurrenceTime: TimeInterval</code>\n</li></ul>\n</li><li><strong>PeriodicEventModel</strong>: Spezialisierung von <code>EventModel</code> (Generalisierungsbeziehung) zur Beschreibung streng periodischer Ereignisse mit den Attributen:\n<ul class=\"fig-list\"><li><code>+ period: TimeInterval</code>\n</li><li><code>+ jitter: TimeInterval</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzablaufdarstellung. Zur Laufzeit bzw. im zeitlichen Verlauf korrespondieren diskrete Ereigniszeitpunkte (<code>occurrenceTime: TimePoint</code>) als Instanzen von <code>EventOccurrence</code> zu einem übergeordneten <code>Event</code>. Die zeitlichen Abstände aufeinanderfolgender Ereignisse werden über <code>EventConstraintOrGuarantee</code> an die durch <code>PeriodicEventModel</code> (feste Periode mit zulässigem Jitter) oder <code>RecurringEventModel</code> (Intervallgrenzen minimaler und maximaler Zwischenankunftszeiten) spezifizierten Zeitintervalle (<code>TimeInterval</code>) gebunden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Metamodell dient als normative Referenz für Timing-Beschreibungen auf VFB-Ebene. Werkzeuge für Timing-Analyse und -Synthese müssen bei der Modellierung von Ereignissen die Unterscheidung zwischen streng periodischem Auftreten (<code>PeriodicEventModel</code>) und aperiodischen bzw. sporadisch wiederkehrenden Ereignissen (<code>RecurringEventModel</code>) beachten. Die Kardinalität <code>1 : *</code> erzwingt, dass jedes <code>EventOccurrence</code> genau einem <code>Event</code> zugeordnet ist, während ein <code>Event</code> beliebig viele Auftretenszeitpunkte aufweisen kann. Ein <code>Event</code> besitzt genau eine Bindung an <code>EventConstraintOrGuarantee</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b9882a054a5d15f3", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung von Ereignissen und zeitlichen Ereignismustern im Kontext des AUTOSAR Virtual Function Bus (VFB) Timing-Modells. Das Diagramm spezifiziert die strukturellen Beziehungen zwischen Ereignisdefinitionen, deren konkreten Instanziierungen bzw. Zeitpunkten sowie zugehörigen zeitlichen Garantien oder Restriktionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst folgende Klassen, Assoziationen und Vererbungsbeziehungen:</p>\n<ul class=\"fig-list\"><li><strong>Event</strong>: Abstrakte Basisentität eines Ereignisses (kursiv dargestellt).\n</li><li><strong>EventOccurrence</strong>: Repräsentiert ein konkretes Auftreten eines Ereignisses mit dem Attribut <code>+ occurrenceTime: TimePoint</code>. Verbunden mit <code>Event</code> über eine Assoziation mit Rollen und Kardinalitäten <code>1</code> (<code>+event</code>) zu <code>*</code> (<code>+occurrences</code>).\n</li><li><strong>EventConstraintOrGuarantee</strong>: Definiert Restriktionen oder Garantien für ein Ereignis mit dem Attribut <code>- constraint or guarantee:</code>. Assoziiert mit <code>Event</code> im Verhältnis <code>1 : 1</code> sowie mit <code>EventModel</code> über eine Assoziation mit Zielkardinalität <code>1</code>.\n</li><li><strong>EventModel</strong>: Abstrakte Basisklasse (kursiv dargestellt) für formale Zeitmodelle von Ereignissen.\n</li><li><strong>RecurringEventModel</strong>: Spezialisierung von <code>EventModel</code> (Generalisierungsbeziehung) zur Modellierung wiederkehrender Ereignisse mit den Attributen:\n<ul class=\"fig-list\"><li><code>+ lowestInterOccurrenceTime: TimeInterval</code>\n</li><li><code>+ highestInterOccurrenceTime: TimeInterval</code>\n</li></ul>\n</li><li><strong>PeriodicEventModel</strong>: Spezialisierung von <code>EventModel</code> (Generalisierungsbeziehung) zur Beschreibung streng periodischer Ereignisse mit den Attributen:\n<ul class=\"fig-list\"><li><code>+ period: TimeInterval</code>\n</li><li><code>+ jitter: TimeInterval</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzablaufdarstellung. Zur Laufzeit bzw. im zeitlichen Verlauf korrespondieren diskrete Ereigniszeitpunkte (<code>occurrenceTime: TimePoint</code>) als Instanzen von <code>EventOccurrence</code> zu einem übergeordneten <code>Event</code>. Die zeitlichen Abstände aufeinanderfolgender Ereignisse werden über <code>EventConstraintOrGuarantee</code> an die durch <code>PeriodicEventModel</code> (feste Periode mit zulässigem Jitter) oder <code>RecurringEventModel</code> (Intervallgrenzen minimaler und maximaler Zwischenankunftszeiten) spezifizierten Zeitintervalle (<code>TimeInterval</code>) gebunden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Metamodell dient als normative Referenz für Timing-Beschreibungen auf VFB-Ebene. Werkzeuge für Timing-Analyse und -Synthese müssen bei der Modellierung von Ereignissen die Unterscheidung zwischen streng periodischem Auftreten (<code>PeriodicEventModel</code>) und aperiodischen bzw. sporadisch wiederkehrenden Ereignissen (<code>RecurringEventModel</code>) beachten. Die Kardinalität <code>1 : *</code> erzwingt, dass jedes <code>EventOccurrence</code> genau einem <code>Event</code> zugeordnet ist, während ein <code>Event</code> beliebig viele Auftretenszeitpunkte aufweisen kann. Ein <code>Event</code> besitzt genau eine Bindung an <code>EventConstraintOrGuarantee</code>.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-5207ea108abe1e63", "to": "FIG-b9882a054a5d15f3", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
